service.method:

INSERT INTO SBUPI (
	 HOUSE_CODE
	,BIZ_CODE
	,SEQ
	,USER_ID
	,ADD_DATE
	,ADD_TIME
	,ADD_USER_ID
	,CHANGE_DATE
	,CHANGE_TIME
	,CHANGE_USER_ID
	,DEL_FLAG
	,USER_NAME
	,EMAIL
	,IF_FLAG
) VALUES (
	 ${session.HOUSE_CODE}
	,${BIZ_CODE}
	,(
		SELECT 
			#DB_OWNER#NVL(MAX(convert(numeric, SEQ)+1),0) MAX_SEQ
	  	FROM 
	  		SBUPI
	 	WHERE 
	 		1=1 
	   		AND BIZ_CODE = 'BITEST2'
	 )
	,${TMP_ID}
	,${current.DATE}
	,${current.TIME}
	,${session.ID}
	,${current.DATE}
	,${current.TIME}
	,${session.ID}
	,'N'
	,${SIGNER_NAME_LOC}
	,${EMAIL}
	,'N'
)
